    card.className = 'card';
    const fav = faviconUrl(b.url);
    card.innerHTML = `
      <div class="card-head">
        ${fav ? `<img class="favicon" src="${fav}" alt="" onerror="this.style.visibility='hidden'" />` : '<span class="favicon"></span>'}
