:root {
  --bg: #f4f5f7;
  --surface: #ffffff;
  --border: #e3e6ea;
  --text: #1b2733;
  --muted: #6b7684;
  --primary: #3b5bdb;
  --primary-hover: #2f4bc4;
  --accent: #f7b500;
  --danger: #e03131;
  --shadow: 0 1px 3px rgba(16, 24, 40, 0.08), 0 1px 2px rgba(16, 24, 40, 0.04);
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 14px 24px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.brand { display: flex; align-items: center; gap: 10px; }
.logo { font-size: 24px; }
.brand h1 { font-size: 20px; margin: 0; font-weight: 700; }

.search-wrap { flex: 1; max-width: 520px; }
#search {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: 15px;
  background: var(--bg);
}
#search:focus { outline: none; border-color: var(--primary); background: #fff; }

.layout {
  display: grid;
  grid-template-columns: 240px 1fr;
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.sidebar { position: sticky; top: 86px; align-self: start; }
.filters { display: flex; flex-direction: column; gap: 4px; margin-bottom: 24px; }
.filter {
  text-align: left;
  padding: 10px 14px;
  border: none;
  background: transparent;
  border-radius: 8px;
  font-size: 15px;
  cursor: pointer;
  color: var(--text);
}
.filter:hover { background: #eceef1; }
.filter.active { background: #e7ecfd; color: var(--primary); font-weight: 600; }

.tags-section h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); margin: 0 0 10px 4px; }
.tag-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
