  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 12px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
}
.tag-list li:hover { background: #eceef1; }
.tag-list li.active { background: #e7ecfd; color: var(--primary); font-weight: 600; }
.tag-list .tag-count { color: var(--muted); font-size: 12px; }

.content-header { display: flex; align-items: baseline; gap: 12px; margin-bottom: 18px; }
.content-header h2 { margin: 0; font-size: 22px; }
.count { color: var(--muted); font-size: 14px; }

.bookmarks-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}
.card:hover { transform: translateY(-2px); box-shadow: 0 4px 12px rgba(16,24,40,0.1); }

.card-head { display: flex; align-items: flex-start; gap: 10px; }
.favicon {
  width: 20px; height: 20px; border-radius: 4px; flex-shrink: 0; margin-top: 2px;
  background: #eceef1;
}
.card-title { font-size: 16px; font-weight: 600; margin: 0; line-height: 1.3; flex: 1; word-break: break-word; }
.card-title a { color: var(--text); text-decoration: none; }
.card-title a:hover { color: var(--primary); }
.star {
  background: none; border: none; cursor: pointer; font-size: 18px; padding: 0;
  color: #cfd4da; line-height: 1;
}
.star.on { color: var(--accent); }

.card-url { font-size: 13px; color: var(--muted); word-break: break-all; text-decoration: none; }
.card-url:hover { text-decoration: underline; }
.card-desc { font-size: 14px; color: #48525d; margin: 0; line-height: 1.4; }

.card-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 2px; }
.chip {
  font-size: 12px; padding: 3px 9px; border-radius: 999px;
  background: #eef1f5; color: #48525d; cursor: pointer;
}
.chip:hover { background: #e0e5eb; }

.card-actions { display: flex; gap: 8px; margin-top: auto; padding-top: 8px; border-top: 1px solid var(--border); }
.card-actions button {
  background: none; border: none; cursor: pointer; font-size: 13px; color: var(--muted); padding: 4px 6px; border-radius: 6px;
}
.card-actions button:hover { background: #f0f1f3; color: var(--text); }
.card-actions .del:hover { color: var(--danger); }

.btn {
  padding: 10px 16px; border-radius: 10px; border: 1px solid var(--border);
  background: #fff; font-size: 14px; font-weight: 600; cursor: pointer; color: var(--text);
}
.btn:hover { background: #f5f6f8; }
.btn-primary { background: var(--primary); color: #fff; border-color: var(--primary); }
.btn-primary:hover { background: var(--primary-hover); }

.empty { text-align: center; padding: 60px 20px; color: var(--muted); }
.empty-emoji { font-size: 48px; margin: 0; }
.empty-title { font-size: 18px; font-weight: 600; color: var(--text); margin: 12px 0 4px; }
.empty-sub { margin: 0; }

.hidden { display: none !important; }

.modal-overlay {
  position: fixed; inset: 0; background: rgba(16,24,40,0.45);
  display: flex; align-items: center; justify-content: center; z-index: 100; padding: 20px;
}
.modal {
  background: #fff; border-radius: 16px; padding: 28px; width: 100%; max-width: 480px;
  box-shadow: 0 20px 40px rgba(16,24,40,0.2);
}
.modal h2 { margin: 0 0 20px; }
#bookmark-form { display: flex; flex-direction: column; gap: 14px; }
#bookmark-form label { display: flex; flex-direction: column; gap: 6px; font-size: 14px; font-weight: 600; }
#bookmark-form label.checkbox { flex-direction: row; align-items: center; font-weight: 500; gap: 8px; }
#bookmark-form input[type="text"], #bookmark-form textarea {
  padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; font-size: 15px; font-family: inherit; font-weight: 400;
}
#bookmark-form input:focus, #bookmark-form textarea:focus { outline: none; border-color: var(--primary); }
.hint { color: var(--muted); font-weight: 400; }
.form-error { color: var(--danger); font-size: 14px; margin: 0; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 6px; }

.toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  background: var(--text); color: #fff; padding: 12px 20px; border-radius: 10px;
  font-size: 14px; z-index: 200; box-shadow: var(--shadow);
}

@media (max-width: 720px) {
  .layout { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .topbar { flex-wrap: wrap; }
  .search-wrap { order: 3; max-width: none; flex-basis: 100%; }
}
